CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(140) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY (user_id, role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id));
INSERT INTO roles(name) VALUES ('ADMIN'), ('MANAGER'), ('TECHNICIAN'), ('WAREHOUSE');
CREATE TABLE equipment_categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE equipment (id BIGINT PRIMARY KEY AUTO_INCREMENT, internal_code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, category_id BIGINT, equipment_type VARCHAR(100), brand VARCHAR(100), model VARCHAR(100), serial_number VARCHAR(120), manufacture_year INT, acquisition_date DATE, fleet_entry_date DATE, meter_type VARCHAR(20), current_meter DECIMAL(14,2), unit_name VARCHAR(100), location VARCHAR(160), cost_center VARCHAR(100), acquisition_value DECIMAL(15,2), supplier_name VARCHAR(180), status VARCHAR(40) NOT NULL DEFAULT 'AVAILABLE', notes TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_equipment_category FOREIGN KEY (category_id) REFERENCES equipment_categories(id), INDEX idx_equipment_name (name), INDEX idx_equipment_status (status), INDEX idx_equipment_category (category_id));
CREATE TABLE equipment_meter_readings (id BIGINT PRIMARY KEY AUTO_INCREMENT, equipment_id BIGINT NOT NULL, meter_value DECIMAL(14,2) NOT NULL, recorded_at DATETIME NOT NULL, recorded_by BIGINT, notes VARCHAR(500), CONSTRAINT fk_meter_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), CONSTRAINT fk_meter_user FOREIGN KEY (recorded_by) REFERENCES users(id), INDEX idx_meter_equipment_date (equipment_id, recorded_at));
CREATE TABLE maintenance_types (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL UNIQUE, description VARCHAR(300));
INSERT INTO maintenance_types(name) VALUES ('PREVENTIVE'), ('CORRECTIVE'), ('PREDICTIVE'), ('INSPECTION'), ('IMPROVEMENT');
CREATE TABLE work_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_number VARCHAR(40) NOT NULL UNIQUE, equipment_id BIGINT NOT NULL, maintenance_type_id BIGINT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', opened_at DATETIME NOT NULL, requested_by BIGINT, assigned_to BIGINT, problem_description TEXT NOT NULL, symptoms TEXT, diagnosis TEXT, failure_cause TEXT, service_performed TEXT, started_at DATETIME, finished_at DATETIME, meter_at_open DECIMAL(14,2), meter_at_close DECIMAL(14,2), downtime_minutes BIGINT, closing_notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_wo_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), CONSTRAINT fk_wo_type FOREIGN KEY (maintenance_type_id) REFERENCES maintenance_types(id), CONSTRAINT fk_wo_requester FOREIGN KEY (requested_by) REFERENCES users(id), CONSTRAINT fk_wo_assignee FOREIGN KEY (assigned_to) REFERENCES users(id), INDEX idx_wo_equipment_status (equipment_id,status), INDEX idx_wo_opened (opened_at), INDEX idx_wo_status_priority (status,priority));
CREATE TABLE work_order_status_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, previous_status VARCHAR(40), new_status VARCHAR(40) NOT NULL, changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, changed_by BIGINT, note VARCHAR(500), CONSTRAINT fk_wo_history_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_wo_history_user FOREIGN KEY (changed_by) REFERENCES users(id), INDEX idx_wo_history_order_date (work_order_id,changed_at));
CREATE TABLE failure_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, equipment_id BIGINT NOT NULL, work_order_id BIGINT, occurred_at DATETIME NOT NULL, failure_mode VARCHAR(180), cause TEXT, corrective_action TEXT, downtime_minutes BIGINT, CONSTRAINT fk_failure_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), CONSTRAINT fk_failure_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id));
CREATE TABLE maintenance_plans (id BIGINT PRIMARY KEY AUTO_INCREMENT, equipment_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, description TEXT, interval_days INT, interval_meter DECIMAL(14,2), last_performed_at DATE, last_meter DECIMAL(14,2), next_due_date DATE, next_due_meter DECIMAL(14,2), estimated_duration_minutes INT, estimated_cost DECIMAL(15,2), active BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_plan_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), INDEX idx_plan_due (active,next_due_date));
CREATE TABLE maintenance_checklists (id BIGINT PRIMARY KEY AUTO_INCREMENT, maintenance_plan_id BIGINT NOT NULL, description VARCHAR(300) NOT NULL, sequence_number INT NOT NULL, required BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_checklist_plan FOREIGN KEY (maintenance_plan_id) REFERENCES maintenance_plans(id));
CREATE TABLE suppliers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, tax_id VARCHAR(30), contact_name VARCHAR(140), email VARCHAR(180), phone VARCHAR(40), address VARCHAR(300), active BOOLEAN NOT NULL DEFAULT TRUE, INDEX idx_supplier_name (name));
CREATE TABLE parts (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(60) NOT NULL UNIQUE, description VARCHAR(180) NOT NULL, category VARCHAR(100), manufacturer VARCHAR(120), manufacturer_code VARCHAR(100), unit VARCHAR(20) NOT NULL, quantity_on_hand DECIMAL(14,3) NOT NULL DEFAULT 0, minimum_quantity DECIMAL(14,3) NOT NULL DEFAULT 0, average_unit_cost DECIMAL(15,4) NOT NULL DEFAULT 0, storage_location VARCHAR(120), supplier_id BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_part_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id), INDEX idx_part_description (description));
CREATE TABLE stock_movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, part_id BIGINT NOT NULL, movement_type VARCHAR(30) NOT NULL, quantity DECIMAL(14,3) NOT NULL, unit_cost DECIMAL(15,4), work_order_id BIGINT, performed_by BIGINT, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, notes VARCHAR(500), CONSTRAINT fk_stock_part FOREIGN KEY (part_id) REFERENCES parts(id), CONSTRAINT fk_stock_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_stock_user FOREIGN KEY (performed_by) REFERENCES users(id), INDEX idx_stock_part_date (part_id,occurred_at));
CREATE TABLE employees (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(160) NOT NULL, employee_code VARCHAR(50) UNIQUE, hourly_cost DECIMAL(12,2), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE work_order_parts (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, part_id BIGINT NOT NULL, quantity DECIMAL(14,3) NOT NULL, unit_cost DECIMAL(15,4) NOT NULL, CONSTRAINT fk_wop_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_wop_part FOREIGN KEY (part_id) REFERENCES parts(id));
CREATE TABLE work_order_labor (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, employee_id BIGINT NOT NULL, hours_worked DECIMAL(10,2) NOT NULL, hourly_cost DECIMAL(12,2) NOT NULL, CONSTRAINT fk_wol_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_wol_employee FOREIGN KEY (employee_id) REFERENCES employees(id));
CREATE TABLE outsourced_services (id BIGINT PRIMARY KEY AUTO_INCREMENT, supplier_id BIGINT NOT NULL, description VARCHAR(250) NOT NULL, reference_code VARCHAR(80), CONSTRAINT fk_outsource_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id));
CREATE TABLE work_order_services (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, supplier_id BIGINT NOT NULL, description VARCHAR(250) NOT NULL, service_date DATE, amount DECIMAL(15,2) NOT NULL, document_reference VARCHAR(100), paid BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_wos_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_wos_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id));
CREATE TABLE cost_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, cost_type VARCHAR(30) NOT NULL, description VARCHAR(250), amount DECIMAL(15,2) NOT NULL, occurred_at DATETIME NOT NULL, source_reference VARCHAR(100), CONSTRAINT fk_cost_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), INDEX idx_cost_date_type (occurred_at,cost_type));
CREATE TABLE attachments (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT, equipment_id BIGINT, file_name VARCHAR(255) NOT NULL, storage_key VARCHAR(500) NOT NULL, content_type VARCHAR(120), uploaded_by BIGINT, uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_attachment_order FOREIGN KEY (work_order_id) REFERENCES work_orders(id), CONSTRAINT fk_attachment_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), CONSTRAINT fk_attachment_user FOREIGN KEY (uploaded_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80) NOT NULL, action VARCHAR(40) NOT NULL, before_state JSON, after_state JSON, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX idx_audit_entity (entity_type,entity_id,occurred_at));
